import{_ as t,o as a,c as i,ao as r}from"./chunks/framework.CfAzH-R8.js";const g=JSON.parse('{"title":"Tutorials","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/index.md","filePath":"tutorials/index.md","lastUpdated":null}'),n={name:"tutorials/index.md"};function s(l,e,o,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="tut-index" tabindex="-1">Tutorials <a class="header-anchor" href="#tut-index" aria-label="Permalink to &quot;Tutorials {#tut-index}&quot;">​</a></h1><p>Mean-field homogenization replaces a heterogeneous microstructure — a matrix carrying inclusions, pores, or cracks — by an equivalent homogeneous medium with the same overall response. <code>MeanFieldHomogenization</code> computes that response from phase properties, geometries, volume fractions, and a <strong>scheme</strong> encoding an assumption about how the phases interact.</p><p>Simplest first within each group. Pages under <code>generated/</code> are produced from the runnable demos in <code>scripts/</code> by <a href="https://github.com/fredrikekre/Literate.jl" target="_blank" rel="noreferrer">Literate.jl</a>.</p><h2 id="Fundamentals" tabindex="-1">Fundamentals <a class="header-anchor" href="#Fundamentals" aria-label="Permalink to &quot;Fundamentals {#Fundamentals}&quot;">​</a></h2><p>The <strong>porous material</strong> gets two pages: the simplest non-trivial microstructure, and the one where the choice of scheme matters most.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">What it shows</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./first_estimate">A first homogenization</a></td><td style="text-align:left;">build an RVE; dilute vs Mori–Tanaka</td></tr><tr><td style="text-align:left;"><a href="./bounds_and_schemes">Bounds and classical schemes</a></td><td style="text-align:left;">Voigt/Reuss bounds, self-consistent, where each scheme sits</td></tr><tr><td style="text-align:left;"><a href="./porous_materials">Porous materials and the self-consistent trap</a></td><td style="text-align:left;">why soft pores break the naive SC iteration</td></tr><tr><td style="text-align:left;"><a href="./porous_benchmark">Porous benchmark: all schemes</a></td><td style="text-align:left;">every scheme on the canonical porosity sweep, spheres and oblate pores</td></tr><tr><td style="text-align:left;"><a href="./transport">Transport properties</a></td><td style="text-align:left;">the same algebra at tensor order 2: diffusivity of a porous medium, anisotropy from oriented pores</td></tr><tr><td style="text-align:left;"><a href="./differential_paths">The differential scheme and path dependence</a></td><td style="text-align:left;">incremental homogenization; why mixing order matters</td></tr><tr><td style="text-align:left;"><a href="./differential_loading_paths">Comparing loading-path trajectories</a></td><td style="text-align:left;">the same target fractions, four trajectories, watched τ by τ</td></tr></tbody></table><h2 id="Inclusions,-geometries-and-orientation" tabindex="-1">Inclusions, geometries and orientation <a class="header-anchor" href="#Inclusions,-geometries-and-orientation" aria-label="Permalink to &quot;Inclusions, geometries and orientation {#Inclusions,-geometries-and-orientation}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">What it shows</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./generated/hill_tensors">Hill polarization tensors in practice</a></td><td style="text-align:left;"><code>hill_tensor</code> on four geometries; residues vs cubature on an anisotropic matrix; the Eshelby tensor against its closed form; <code>P</code> → a dilute estimate</td></tr><tr><td style="text-align:left;"><a href="./cracks">Cracks and crack density</a></td><td style="text-align:left;">volume fraction → crack density; the COD tensor</td></tr><tr><td style="text-align:left;"><a href="./generated/crack_distributions">Crack distributions: isotropic or parallel</a></td><td style="text-align:left;">the same density, two orientation rules; the two self-consistent forms and their two percolation thresholds (9/16 exactly for the compliance form, ≈ 1.158 for the stiffness one); the local-versus-global frame of a <code>TensRotated</code> result</td></tr><tr><td style="text-align:left;"><a href="./fe_crack">Validating a finite-element crack</a></td><td style="text-align:left;">the same crack solved by finite elements: what the corrected boundary condition buys, and convergence to the closed-form COD</td></tr><tr><td style="text-align:left;"><a href="./generated/layered_sphere">Layered spheres</a></td><td style="text-align:left;">Hervé–Zaoui <code>n</code>-layer localization and layer averages</td></tr><tr><td style="text-align:left;"><a href="./generated/layered_spheroid_effective">Layered spheroids: geometry and effective conductivity</a></td><td style="text-align:left;">the confocal <code>n</code>-layer spheroid, the equivalent particle, harmonic-series accuracy</td></tr><tr><td style="text-align:left;"><a href="./generated/layered_spheroid_interfaces">Imperfect interfaces: what they do to the local fields</a></td><td style="text-align:left;">pointwise temperature and flux, streamlines, conductance sweep, 3-D view</td></tr><tr><td style="text-align:left;"><a href="./generated/layered_spheroid_hc">Highly conducting interfaces</a></td><td style="text-align:left;">equivalent conductivity of an HC-coated particle vs aspect ratio</td></tr><tr><td style="text-align:left;"><a href="./generated/nano_spheroids">Nanocomposites: the equivalent particle</a></td><td style="text-align:left;">Dormieux, Lemarchand &amp; Brisard (2016): a Gurtin-Murdoch interface condensed into a particle stiffness, its three limiting shapes reproduced exactly, and the size effect it produces through an ordinary Mori-Tanaka estimate — no new scheme needed</td></tr><tr><td style="text-align:left;"><a href="./generated/laminate">Periodic multilayer: the exact laminate solution</a></td><td style="text-align:left;">a cell with no matrix and no Eshelby problem: the exact effective tensor, per-layer localization, the bounds it saturates</td></tr><tr><td style="text-align:left;"><a href="./generated/laminate_interfaces">Imperfect interfaces in a laminate, and the size effect</a></td><td style="text-align:left;">the four interface models on a planar interface, and the interface <em>density</em> that makes the period matter</td></tr><tr><td style="text-align:left;"><a href="./generated/symmetrization">Symmetrization</a></td><td style="text-align:left;">exact rotation-group average vs best-fit projection</td></tr><tr><td style="text-align:left;"><a href="./generated/custom_inclusion_contract">The custom-inclusion contract</a></td><td style="text-align:left;">plugging an arbitrary morphology into every scheme — the three entry gates, the density seam, free orientation averaging</td></tr><tr><td style="text-align:left;"><a href="./generated/neural_inclusion">An inclusion whose response is a neural network</a></td><td style="text-align:left;">both phases — how a surrogate is <strong>trained</strong> (schematics of the network and of the fitting loop, the recorded learning curve) and how a trained one is <strong>used</strong>: what stays exact whatever the fit, accuracy against the closed form, every scheme, and the derivative with respect to the <em>morphology</em></td></tr><tr><td style="text-align:left;"><a href="./generated/neural_excentered_sphere">Replacing a finite-element solve by a surrogate</a></td><td style="text-align:left;">the case the machinery exists for: the eccentric-core sphere, whose localization tensors have no closed form. Gate B with the 6-component transversely isotropic pair, the contrast ratios that replace gate A&#39;s homogeneity, the accuracy against the finite elements, the speed-up, and a derivative with respect to the <strong>eccentricity</strong></td></tr></tbody></table><p>Composite inclusions carry no Hill tensor at all: they enter the schemes through their volume-averaged concentration tensors instead.</p><h2 id="Interacting-particle-assemblies" tabindex="-1">Interacting particle assemblies <a class="header-anchor" href="#Interacting-particle-assemblies" aria-label="Permalink to &quot;Interacting particle assemblies {#Interacting-particle-assemblies}&quot;">​</a></h2><p>The two <strong>N-body</strong> schemes. Every other scheme of the package sees a single inclusion in a reference medium and averages the interaction; these two resolve it inclusion by inclusion, so they need a <code>ParticleAssembly</code> — a cell that carries positions — rather than an <code>RVE</code>. Both are built on the same two-inclusion interaction tensor.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tutorial</th><th style="text-align:left;">What it shows</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./generated/cluster_model">The cluster model on cubic arrays</a></td><td style="text-align:left;">Molinari &amp; El Mouden (1996): convergence in cluster radius, the exact degeneracy onto Mori-Tanaka when the cluster is empty, comparison with the one-site schemes, the bulk modulus that stays exactly Mori-Tanaka whatever the arrangement, and SC vs BCC vs FCC porous arrays</td></tr><tr><td style="text-align:left;"><a href="./generated/multiscale_assemblies">Chaining scales through an N-body scheme</a></td><td style="text-align:left;">the declarative multiscale seam with an assembly on either side, and why chaining two N-body estimates needs the <em>anisotropic</em> Green operator: a cluster estimate on a cubic array is cubic, not isotropic. Three scales end to end, plus a sensitivity across them</td></tr><tr><td style="text-align:left;"><a href="./generated/eim_assembly">The equivalent inclusion method</a></td><td style="text-align:left;">Brisard, Dormieux &amp; Sab (2014), Table 1: 160 circular pores in a circular SVE, plane strain — the <code>p = 0</code> bound reproduced by Monte-Carlo, against the Hashin-Shtrikman bound it improves on and the finite-element value it bounds</td></tr></tbody></table><p>Theory: <a href="/MeanFieldHomogenization.jl/stable/theory/interaction_tensors#th-interaction">interaction tensors</a>, <a href="/MeanFieldHomogenization.jl/stable/theory/cluster_model#th-cluster">the cluster model</a>, <a href="/MeanFieldHomogenization.jl/stable/theory/eim#th-eim">the equivalent inclusion method</a>; the API is on the <a href="/MeanFieldHomogenization.jl/stable/manual/particle_assemblies#man-assemblies">particle-assembly manual page</a>.</p><h2 id="Beyond-elasticity" tabindex="-1">Beyond elasticity <a class="header-anchor" href="#Beyond-elasticity" aria-label="Permalink to &quot;Beyond elasticity {#Beyond-elasticity}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">What it shows</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./viscoelasticity">Viscoelastic composites</a></td><td style="text-align:left;">complex moduli in the frequency domain; a first taste of ageing creep</td></tr><tr><td style="text-align:left;"><a href="./generated/rheological_models">The rheological model catalog</a></td><td style="text-align:left;">the classical chains, the fractional family and the bituminous models side by side; master curves, Cole-Cole and Black diagrams; the exact 2S2P1D pair in both domains; and one object driving both homogenization routes</td></tr><tr><td style="text-align:left;"><a href="./generated/kelvin_maxwell">Generalized Kelvin ⇄ generalized Maxwell</a></td><td style="text-align:left;">the exact conversion between the two representations: the interlacing that makes it unconditionally robust, the round trip at twenty branches, and two independent closed forms — the Zener relations and the Burgers relaxation function — as oracles</td></tr><tr><td style="text-align:left;"><a href="./generated/laplace_inversion">Choosing a numerical Laplace inversion</a></td><td style="text-align:left;">four algorithms measured against four exact pairs; why branch cuts are not the problem and oscillation is; the Gaver-Stehfest optimum and why more terms is worse; <code>ForwardDiff</code> straight through</td></tr><tr><td style="text-align:left;"><a href="./generated/freq_vs_time">Frequency or time?</a></td><td style="text-align:left;">the complex-modulus and time-domain ALV routes, cross-checked on the same non-ageing composite</td></tr><tr><td style="text-align:left;"><a href="./generated/alv_schemes">Ageing viscoelastic schemes side by side</a></td><td style="text-align:left;">Dilute / Mori-Tanaka / Maxwell / PCW on one creep test; the aspect ratio; where the distribution shape decides the answer</td></tr><tr><td style="text-align:left;"><a href="./generated/ageing_ages_aspect">Ageing creep: loading age against inclusion shape</a></td><td style="text-align:left;">ageing and morphology on the same output: three loading ages × three aspect ratios, and why the shape effect is an offset independent of the age</td></tr><tr><td style="text-align:left;"><a href="./generated/laminate_alv">A creeping laminate</a></td><td style="text-align:left;">the exact multilayer in ageing viscoelasticity: the same algebra with Volterra products in place of tensor products</td></tr><tr><td style="text-align:left;"><a href="./generated/alv_sensitivities">Derivatives through the ageing-viscoelastic pipeline</a></td><td style="text-align:left;"><code>ForwardDiff</code> through the Volterra assembly: the <code>set_param</code> lens for RVE parameters, closure capture for moduli and relaxation times</td></tr></tbody></table><h2 id="Differentiation-and-solvers" tabindex="-1">Differentiation and solvers <a class="header-anchor" href="#Differentiation-and-solvers" aria-label="Permalink to &quot;Differentiation and solvers {#Differentiation-and-solvers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">What it shows</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./sensitivities">Derivatives and sensitivities</a></td><td style="text-align:left;">differentiate any result with <code>ForwardDiff</code>, no finite differences</td></tr><tr><td style="text-align:left;"><a href="./strength_criteria">From derivatives to a strength criterion</a></td><td style="text-align:left;">those derivatives as a macroscopic strength criterion</td></tr><tr><td style="text-align:left;"><a href="./nonlinear_solvers">Nonlinear solvers for the self-consistent fixed point</a></td><td style="text-align:left;"><code>NonlinearSolve.jl</code> instead of Picard, and sensitivities that agree either way</td></tr><tr><td style="text-align:left;"><a href="./generated/secant_elastoplasticity">Nonlinear homogenization by the secant method</a></td><td style="text-align:left;">elastic–perfectly plastic porous solid, closed by second moments</td></tr></tbody></table><h2 id="Interoperability-and-tools" tabindex="-1">Interoperability and tools <a class="header-anchor" href="#Interoperability-and-tools" aria-label="Permalink to &quot;Interoperability and tools {#Interoperability-and-tools}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">What it shows</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./symbolic_spheres">Symbolic spheres</a></td><td style="text-align:left;">the same tensor algebra on <code>SymPy</code> / <code>Symbolics</code> expressions: Eshelby/Hill tensors and the closed-form estimates</td></tr><tr><td style="text-align:left;"><a href="./symbolic_laminate">Symbolic laminates: arithmetic and harmonic averages</a></td><td style="text-align:left;">the one microstructure whose effective behavior is a closed form, derived symbolically</td></tr><tr><td style="text-align:left;"><a href="./symbolic_viscoelasticity">Symbolic viscoelasticity</a></td><td style="text-align:left;">models with symbolic parameters, and symbolic Laplace-Carson inversion: the Burgers relaxation function <em>derived</em> rather than transcribed, and precisely where the symbolic route stops</td></tr><tr><td style="text-align:left;"><a href="./generated/laminate_multiscale">Multiscale chaining: explicit and declarative, side by side</a></td><td style="text-align:left;">the two ways of chaining scales, the same answer, and the <code>ForwardDiff</code> pass that goes through both</td></tr></tbody></table>',19)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
